// ===== CONFIG (igual que Santa Rosa) =====
const CFG = { zona: 'America/Montevideo', abre: 9, cierra: 20, dias: [1,2,3,4,5], feriados: [], horasToque1: 3, topeSesionHs: 24 };
const habil = d => CFG.dias.includes(d.weekday) && !CFG.feriados.includes(d.toISODate());
const abrir = d => d.set({ hour: CFG.abre, minute: 0, second: 0, millisecond: 0 });
function ajustar(d) {
  let x = d;
  if (x.hour >= CFG.cierra) x = abrir(x.plus({ days: 1 }));
  else if (x.hour < CFG.abre) x = abrir(x);
  while (!habil(x)) x = abrir(x.plus({ days: 1 }));
  return x;
}
const ultimo = DateTime.fromISO($json.ultimo_msg_lead, { zone: CFG.zona });
const base = (ultimo.isValid ? ultimo : DateTime.now().setZone(CFG.zona)).plus({ hours: CFG.horasToque1 });
let envio = ajustar(base);
if (ultimo.isValid && envio.diff(ultimo, 'hours').hours > CFG.topeSesionHs) {
  envio = abrir(ultimo.plus({ days: 1 }));
  if (envio < base) envio = base;
}
const fila = { lead_id: $json.lead_id, nombre: ($json.nombre || '').split(' ')[0] || null, apellido: ($json.nombre || '').split(' ').slice(1).join(' ') || null, telefono: $json.telefono, email: $json.email || null, modelo: $json.modelo || null, origen: $json.origen || null, notas: $json.notas_pilot || null, proximo_envio_at: envio.toUTC().toFormat('yyyy-MM-dd HH:mm:ss'), extra: { marca: $json.marca || null, grupo_original: $json.grupo_original || null, fecha_consulta: $json.fecha_consulta, ultimo_msg_lead: $json.ultimo_msg_lead, toques: {} } };
return { json: { ...$json, proximo_envio: envio.toISO(), fila: JSON.stringify(fila) } };

